```tsx
import {useMemo, useRef, useState} from 'react';
import type {ChartEngineProps} from '../types';
import {useMeasure} from '../useMeasure';
import {niceCeil, niceTicks} from '../scale';
import {seriesColor} from '../colors';
import {ChartTooltip, type TooltipEntry} from '../ChartTooltip';
import {usePrefersDark} from '../usePrefersDark';

const MARGIN = {top: 16, right: 76, bottom: 28, left: 60};

export default function SalesLineChart({series, height = 320, formatValue, formatTime}: ChartEngineProps) {
  const [wrapRef, size] = useMeasure<HTMLDivElement>();
  const dark = usePrefersDark();
  const [hoverIdx, setHoverIdx] = useState<number | null>(null);

  const width = size.width;
  const plotW = Math.max(0, width - MARGIN.left - MARGIN.right);
  const plotH = Math.max(0, height - MARGIN.top - MARGIN.bottom);

  const model = useMemo(() => {
    if (!series.length || !series[0].points.length) return null;
    const pts = series[0].points;
    const maxV = Math.max(...series.flatMap(s => s.points.map(p => p.v)), 0);
    const yMax = niceCeil(maxV);
    const ticks = niceTicks(0, yMax);
    const stepX = pts.length > 1 ? plotW / (pts.length - 1) : 0;
    const x = (i: number) => MARGIN.left + i * stepX;
    const y = (v: number) => MARGIN.top + plotH - (v / yMax) * plotH;
    return {pts, yMax, ticks, stepX, x, y};
  }, [series, plotW, plotH]);
  ...
}
```

