/** Round, clean axis ticks shared by both engines. */

export function niceTicks(min: number, max: number, count = 4): number[] {
  const span = max - min || 1;
  const step0 = span / count;
  const mag = Math.pow(10, Math.floor(Math.log10(step0)));
  const norm = step0 / mag;
  const step = (norm >= 5 ? 10 : norm >= 2 ? 5 : norm >= 1 ? 2 : 1) * mag;
  const lo = Math.ceil(min / step) * step;
  const hi = Math.floor(max / step) * step;
  const ticks: number[] = [];
  for (let v = lo; v <= hi + step * 1e-6; v += step) {
    ticks.push(+v.toPrecision(12));
  }
  return ticks;
}

/** Smallest "nice" ceiling >= max, with room for the tick row above it. */
export function niceCeil(max: number, count = 4): number {
  if (max <= 0) return 1;
  const step0 = max / count;
  const mag = Math.pow(10, Math.floor(Math.log10(step0)));
  const norm = step0 / mag;
  const step = (norm >= 5 ? 10 : norm >= 2 ? 5 : norm >= 1 ? 2 : 1) * mag;
  return Math.ceil(max / step) * step;
}

