  align-items: baseline;
  gap: 6px;
  padding: 1px 0;
}

.ck-tooltip__key {
  width: 12px;
  height: 3px;
  border-radius: 2px;
  align-self: center;
  flex: none;
}

.ck-tooltip__name {
  color: var(--ck-text-secondary);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ck-tooltip__value {
  color: var(--ck-text-primary);
  font-variant-numeric: tabular-nums;
}

/* legend */

.ck-legend {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  margin: 2px 0 6px;
}

.ck-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 4px;
  border: 0;
  background: none;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  color: var(--ck-text-primary);
}

.ck-legend__item[data-off] {
  opacity: 0.4;
}

.ck-legend__key {
  width: 14px;
  height: 3px;
  border-radius: 2px;
}

/* table view */

.ck-table-wrap {
  max-height: 360px;
  overflow: auto;
}

.ck-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.ck-table th {
  position: sticky;
  top: 0;
  background: var(--ck-surface);
  color: var(--ck-text-secondary);
  text-align: left;
  font-weight: 500;
  padding: 6px 12px 6px 0;
  border-bottom: 1px solid var(--ck-baseline);
}

.ck-table td {
  padding: 4px 12px 4px 0;
  border-bottom: 1px solid var(--ck-grid);
  color: var(--ck-text-primary);
}

