// Renders the built widget in headless Chromium and captures both modes.
import {chromium} from 'playwright';

const BASE = process.env.BASE_URL ?? 'http://localhost:4173';

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1100, height: 640}});

// Track lazy chunk loads to prove engines load on demand.
const requests = [];
page.on('request', (r) => {
  if (r.url().includes('LineChart') || r.url().includes('MonitoringChart')) {
    requests.push(r.url().split('/').pop());
  }
});

await page.goto(BASE, {waitUntil: 'networkidle'});
await page.waitForSelector('svg', {timeout: 10000});
await page.screenshot({path: '/tmp/shot-sales.png'});

await page.getByText('Мониторинг', {exact: true}).click();
await page.waitForSelector('canvas', {timeout: 10000});
await page.waitForTimeout(400);
await page.screenshot({path: '/tmp/shot-monitoring.png'});

await page.getByRole('button', {name: 'Таблица'}).click();
await page.waitForSelector('table', {timeout: 10000});
await page.screenshot({path: '/tmp/shot-table.png'});

console.log('lazy engine chunks fetched:', requests.join(', '));
await browser.close();

